fn solve(a: i8, b: i8, s: Vec<char>) -> Vec<char> {
    // Convert a to usize for indexing
    let a = a as usize;

    // Count how many hyphens are in the input
    let hyphen_count = s.iter().filter(|&&c| c == '-').count();

    // Check there is exactly one hyphen and that it is at position a
    let hyphen_at_correct_pos = s.get(a) == Some(&'-');

    // Check that every other character is a digit
    let other_are_digits = s.iter()
        .enumerate()
        .all(|(i, &c)| {
            if i == a {
                true
            } else {
                c.is_ascii_digit()
            }
        });

    if hyphen_count == 1 && hyphen_at_correct_pos && other_are_digits {
        vec!['Y', 'e', 's']
    } else {
        vec!['N', 'o']
    }
}

fn main() {
    // Example tests
    assert_eq!(solve(3, 4, "123-5678".chars().collect()), vec!['Y','e','s']);
    assert_eq!(solve(3, 4, "12-35678".chars().collect()), vec!['N','o']);
    assert_eq!(solve(1, 1, "-12".chars().collect()),       vec!['N','o']);
    assert_eq!(solve(1, 1, "1-2".chars().collect()),       vec!['Y','e','s']);
}